// 1. Extract incoming payload
const body = $input.first().json.body || $input.first().json;

// 2. Data Cleaning & Normalization
const rawName = (body.name || 'Valued Lead').trim();
const cleanName = rawName.replace(/\b\w/g, char => char.toUpperCase());

const rawEmail = (body.email || '').trim().toLowerCase();
const rawPhone = (body.phone || '').toString().replace(/[^0-9]/g, '');
const cleanPhone = rawPhone.length === 10 ? '91' + rawPhone : rawPhone;

const service = body.service || 'General Inquiry';
const budget = Number(body.budget) || 0;

// 3. Lead Scoring & Prioritization
let priority = 'Standard Lead 📌';
if (budget >= 30000) {
  priority = 'HIGH PRIORITY 🔥';
} else if (budget >= 15000) {
  priority = 'Medium Priority ⚡';
}

// 4. Timestamp & Tracking ID
const leadId = 'LD-' + Date.now().toString().slice(-6);
const receivedAt = new Date().toISOString().replace('T', ' ').substring(0, 19);

return {
  lead_id: leadId,
  name: cleanName,
  email: rawEmail,
  phone: cleanPhone,
  service: service,
  budget: budget,
  priority: priority,
  received_at: receivedAt,
  whatsapp_link: `https://wa.me/${cleanPhone}?text=Hello%20${encodeURIComponent(cleanName)},%20thank%20you%20for%20contacting%20us.`
};

